import re
import operator
import logging
import datetime
import inspect

from taf.analyzer.ims2 import Ims2ChangesetLogEntry, Ims2LogReader, Ims2ResetLogEntry
from taf.ul.oam_kpi_calculations.provider import Provider
from taf.ul.oam_kpi_calculations.exceptions import DataNotAvailable
from taf.ul.oam_kpi_calculations.parsers.ims.events import (SiteResetRequest, SequenceOfEvents, AnyStatus, OneOfEvents,
                                                            AllEvents)
from taf.ul.oam_kpi_calculations.parsers.ims.statuses import ValueProperty
from taf.ul.oam_kpi_calculations.parsers.ims.patterns import DistNamePatterns
from taf.ul.oam_kpi_calculations.alarm.alarm_event_detection import AlarmEventDetection
from taf.ul.oam_kpi_calculations.utilities import merge_and_sort_ims_files, get_mrbts_from_log_entry


class Calculator(object):
    OPERATORS = {
        # For non regex
        ">": operator.gt,
        ">=": operator.ge,
        "!": operator.ne,
        "!=": operator.ne,
        "=": operator.eq,
        "==": operator.eq,
        "<": operator.lt,
        "<=": operator.le,
        # For regex
        "match": operator.truth,
        "not match": operator.not_,
    }

    def __init__(self, kpi_names, ims_file_path, kpi_params=None, log_warning=True, serial_console_connected=False,
                 merge_ims_files=False):
        """
        Calculate start_points/end_points for passed KPI
        :param str, list kpi_names: KPI names all names available in provider.SupportedKpi
        :param str, list ims_file_path: path to ims2 log file or list of paths
        :param dict kpi_params:  additional KPI params
        :param bool log_warning:  True/False - logging warning when kpi cannot be calculated.
        :param bool serial_console_connected:  True/False - for console connected some KPI has different endpoint
        :param bool merge_ims_files:  True/False - merge all IMS files into one IMS file before calculations.
        """

        self.kpi_names = self._get_kpi_names(kpi_names)
        self.kpis = self._get_kpi_instances(kpi_params, serial_console_connected)
        self.ims_file_path = ims_file_path if isinstance(ims_file_path, (list, tuple)) else [ims_file_path]
        self.log_warning = log_warning
        self.merge_ims_files = merge_ims_files
        self.alarm = AlarmEventDetection()
        self._current_ims_file = None
        self._mrbts_id = None
        self._mrbts_ids = set()

        self._previous_log_entry_timestamp = {}
        self._ignored_frames = []
        self._ignoring_log_printed = False

    def calculate(self, search_start_timestamp=None, search_end_timestamp=None):  # noqa: C901
        """
        Calculate start_points/end_points for passed KPI
        :param datetime search_start_timestamp: if passed search only for timestamp >  search_start_timestamp
        :param datetime search_end_timestamp: if passed search only for timestamp <  search_end_timestamp
        :return:
        """

        self._setup_alarms()

        for frame_index, log_entry, kpi in self._get_log_entry_and_kpi():
            if not self.merge_ims_files and self.ims_file_path.index(self._current_ims_file) > 0:
                # Maybe first frame should not be ignored?
                if self._ignore_duplicated_frames(frame_index, log_entry, kpi):
                    continue
            if isinstance(log_entry, Ims2ChangesetLogEntry):
                self._check_if_alarm_occurred(log_entry)
            elif isinstance(log_entry, Ims2ResetLogEntry):
                self.alarm.reset_detected_alarm_events(reset_type='Site Reset', timestamp=log_entry.timestamp)
            if self._is_entry_in_time_range(log_entry.timestamp, search_start_timestamp, search_end_timestamp):
                self._calculate_min_frame_interval(kpi, log_entry)
                self._calculate_kpi_body(frame_index, kpi, log_entry)
            if isinstance(log_entry, Ims2ChangesetLogEntry):
                active_alarms_before = False
                if self.alarm.active_alarms:
                    active_alarms_before = True
                self._check_if_alarm_removed(log_entry)
                if active_alarms_before and not self.alarm.active_alarms and kpi.current_iteration.alarms['before']:
                    self.alarm.reset_detected_alarm_events(reset_type='All alarms cleared - Potential Power Reset',
                                                           timestamp=log_entry.timestamp)

        self._end_iteration_if_not_ended()
        self._teardown_alarms()

    def _ignore_duplicated_frames(self, frame_index, log_entry, kpi):
        skip_frame = False
        if kpi.name in self._previous_log_entry_timestamp and \
                self._previous_log_entry_timestamp[kpi.name] >= log_entry.timestamp:
            if not self._ignoring_log_printed:
                logging.debug("Ignoring frame [{}] from [{}] because current frame "
                              "timestamp [{}] '<=' previous frame timestamp [{}]".
                              format(frame_index, self._current_ims_file,
                                     self._previous_log_entry_timestamp[kpi.name], log_entry.timestamp))
                self._ignoring_log_printed = True
            self._ignored_frames.append((frame_index, log_entry.timestamp))
            skip_frame = True
        elif self._ignoring_log_printed:
            logging.debug("Ignored {} frames in a row. Last ignored frame [{}][{}] from [{}]".
                          format(len(self._ignored_frames), self._ignored_frames[-1][0], self._ignored_frames[-1][1],
                                 self._current_ims_file))
            self._ignoring_log_printed = False
            self._ignored_frames = []
        return skip_frame

    def _calculate_kpi_body(self, frame_index, kpi, log_entry):  # noqa: C901
        if kpi.start_search_after and isinstance(kpi.start_search_after, datetime.datetime):
            if kpi.start_search_after > log_entry.timestamp:
                return
        if isinstance(kpi.start_point, datetime.datetime) and not \
                kpi.current_iteration.start_point_timestamp:
            kpi.current_iteration.start_point_timestamp = kpi.start_point
            kpi.current_iteration.first_start_point_entry_timestamp = kpi.start_point
            kpi.propagate_start_point_timestamp_for_all_mrbts(mrbts_ids=self._mrbts_ids)

        if isinstance(log_entry, Ims2ResetLogEntry):
            if kpi.current_iteration.site_reset_timestamp is None:
                kpi.current_iteration.site_reset_timestamp = log_entry.timestamp
            self._log_debug_for_detected_point('RST Event', frame_index, None, log_entry, kpi)
            if isinstance(kpi.start_point, SiteResetRequest):
                kpi.current_iteration.start_point_timestamp = kpi.current_iteration.site_reset_timestamp
                kpi.current_iteration.first_start_point_entry_timestamp = kpi.current_iteration.site_reset_timestamp
                kpi.propagate_start_point_timestamp_for_all_mrbts(mrbts_ids=self._mrbts_ids)
        elif isinstance(log_entry, Ims2ChangesetLogEntry):
            self._check_if_kpi_entry(frame_index, kpi, log_entry)

    def _calculate_min_frame_interval(self, kpi, log_entry):
        if kpi.name in self._previous_log_entry_timestamp:
            interval = log_entry.timestamp - self._previous_log_entry_timestamp[kpi.name]
            rounded_interval = round(interval.total_seconds(), 3)
            if kpi.current_iteration.min_ims_record_interval is None:
                kpi.current_iteration.min_ims_record_interval = rounded_interval
            elif rounded_interval < kpi.current_iteration.min_ims_record_interval:
                kpi.current_iteration.min_ims_record_interval = rounded_interval
        self._previous_log_entry_timestamp[kpi.name] = log_entry.timestamp

    def _get_log_entry_and_kpi(self):
        for frame_number, log_entry in self._get_log_entry():
            for kpi in self.kpis:
                yield frame_number, log_entry, kpi

    def _get_log_entry(self):
        if self.merge_ims_files:
            logging.debug("Merging IMS files: {}".format(self.ims_file_path))
            merged_ims_files, self._mrbts_ids = merge_and_sort_ims_files(ims_file_paths=self.ims_file_path)
            for entry in merged_ims_files:
                self._current_ims_file = entry['file_path']
                self._mrbts_id = entry['mrbts_id']
                yield entry['frame'], entry['entry']
        else:
            for file_path in self.ims_file_path:
                self._current_ims_file = file_path
                logging.debug("Start processing: {}".format(self._current_ims_file))
                for frame_number, log_entry in enumerate(Ims2LogReader.from_file(file_path=self._current_ims_file)):
                    if frame_number == 0:
                        self._mrbts_id = get_mrbts_from_log_entry(log_entry)
                    yield frame_number, log_entry

    def _get_dist_name_and_value(self, log_entry, kpi):
        log_entries = {
            'updates': log_entry.updates,
        }
        if self._kpi_definition_uses_removals_entries(kpi):
            log_entries['removals'] = log_entry.removals

        for entry_type in log_entries:
            entries = getattr(log_entry, entry_type)
            for dist_name in entries:
                value = entries[dist_name] if isinstance(entries, dict) else None
                yield dist_name, value, entry_type

    @staticmethod
    def _kpi_definition_uses_removals_entries(kpi):  # noqa: C901
        all_points = [kpi.start_point, kpi.end_point]
        if kpi.start_search_after:
            all_points.append(kpi.start_search_after)
        for point in all_points:
            if isinstance(point, (OneOfEvents, AllEvents)):
                events = point.events
            elif isinstance(point, SequenceOfEvents):
                events = [event['event'] for event in point.events]
            else:
                events = [point]

            for single_event in events:
                if hasattr(single_event, 'entry_type') and single_event.entry_type == 'removals':
                    return True
        return False

    @staticmethod
    def _is_entry_in_time_range(current_time, start, end):
        """
        Check if current time fall in range between star and end
        :param datetime current_time: Current time from IMS log
        :param datetime start: defined start time
        :param datetime end:  defined end time
        :return bool: True/False
        """
        if not start and not end:
            return True
        elif not start and end and current_time <= end:
            return True
        elif start and not end and current_time >= start:
            return True
        elif start and end and start <= current_time <= end:
            return True

        return False

    def _setup_alarms(self):
        self.alarm.clear_variables()

    def _teardown_alarms(self):
        self.alarm.move_detected_alarms_to_all_alarm_events()

    def _end_iteration_if_not_ended(self):
        for kpi in self.kpis:
            if kpi.current_iteration.is_iteration_started():
                logging.debug("End of IMS file and iteration not ended - ending iteration")
                self._end_iteration(kpi)

    def _check_if_kpi_entry(self, frame_index, kpi, log_entry):
        indication_point_dist_name = ''
        for dist_name, value, entry_type, in self._get_dist_name_and_value(log_entry, kpi):
            if kpi.start_search_after and not kpi.current_iteration.indication_point:
                indication_point_dist_name = 'not_set'
            self._add_entries_if_conditions_met(frame_index, kpi, log_entry, dist_name, entry_type)

            if kpi.start_search_after and kpi.current_iteration.indication_point \
                    and indication_point_dist_name == 'not_set':
                indication_point_dist_name = dist_name
                # in case when Start Point is in the same log_entry like Indication Point
                for _dist_name, _value, _entry_type, in self._get_dist_name_and_value(log_entry, kpi):
                    if _dist_name != indication_point_dist_name:
                        self._add_entries_if_conditions_met(frame_index, kpi, log_entry, _dist_name, _entry_type)
                break

    def _check_if_alarm_occurred(self, log_entry):
        for dist_name, value in log_entry.updates.items():
            if re.search(DistNamePatterns.ALARM, dist_name):
                self.alarm.mark_alarm_as_set(alarm_dist_name=dist_name,
                                             timestamp=log_entry.timestamp,
                                             details=log_entry.updates[dist_name])

    def _check_if_alarm_removed(self, log_entry):
        for dist_name in log_entry.removals:
            if re.search(DistNamePatterns.ALARM, dist_name):
                self.alarm.mark_alarm_as_removed(alarm_dist_name=dist_name, timestamp=log_entry.timestamp)

    def _add_entries_if_conditions_met(self, frame_index, kpi, log_entry, dist_name, entry_type):  # noqa: C901
        """
        Add entries to KPI object if dis_name and statuses matched
        :param kpi: KPI object
        :param log_entry: IMS log entry
        :param dist_name: dis_name
        :return:
        """
        entries = getattr(log_entry, entry_type)
        values = entries[dist_name] if isinstance(entries, dict) else None
        if self._check_if_indication_event(kpi, dist_name, log_entry, entry_type):
            if isinstance(kpi.start_search_after, SequenceOfEvents) and kpi.start_search_after.next_event_record:
                self._log_debug_for_detected_point('SEQUENCE OF INDICATION', frame_index, dist_name,
                                                   log_entry, kpi, entry_type)
                kpi.add_debug_indication_entry(dist_name=dist_name, value=values, timestamp=log_entry.timestamp)
                kpi.start_search_after.update_next_event(dist_name=dist_name, values=values)
                return
            if kpi.min_offset_between_indication_points and kpi.current_iteration.indication_point:
                if kpi.current_iteration.indication_point[0]['timestamp'] + \
                        kpi.min_offset_between_indication_points > log_entry.timestamp:
                    self._log_debug_for_ignored_entry(
                        reason="'min_offset_between_indication_points' is set",
                        entry_type='INDICATION', dist_name=dist_name,
                        frame_index=frame_index, log_entry=log_entry, kpi=kpi)
                    return
            if kpi.current_iteration.first_start_point_entry_timestamp and kpi.min_start_and_end_point_offset:
                if kpi.current_iteration.first_start_point_entry_timestamp + \
                        kpi.min_start_and_end_point_offset > log_entry.timestamp:
                    self._log_debug_for_ignored_entry(
                        reason="'min_start_and_end_point_offset' is set",
                        entry_type='INDICATION', dist_name=dist_name,
                        frame_index=frame_index, log_entry=log_entry, kpi=kpi)
                    return

            current_indication_dist_name = self._get_current_indication_dist_name(kpi)
            if current_indication_dist_name and current_indication_dist_name == dist_name:
                # TODO Add checking based on ALARM events
                self._log_debug_for_ignored_entry(
                    reason="DistName is the same like in current iteration",
                    entry_type='INDICATION', dist_name=dist_name,
                    frame_index=frame_index, log_entry=log_entry, kpi=kpi)
                return
            if kpi.current_iteration.indication_point and \
                    (not kpi.multi_indication or (kpi.multi_indication and kpi.current_iteration.start_point_entries)):
                logging.debug("Ending previous iteration - new indication point detected")
                self._end_iteration(kpi)
            self._log_debug_for_detected_point('INDICATION', frame_index, dist_name, log_entry, kpi,
                                               entry_type)
            kpi.add_debug_indication_entry(dist_name=dist_name, value=values, timestamp=log_entry.timestamp)
            kpi.add_indication_entry(dist_name=dist_name, value=values, timestamp=log_entry.timestamp,
                                     mrbts_id=self._mrbts_id)
            kpi.add_alarms_before_iteration(self.alarm.active_alarms)

        elif kpi.start_search_after and not kpi.current_iteration.indication_point:
            return

        if kpi.current_iteration.required_alarms:
            for alarm in kpi.required_alarms:
                if self.alarm.alarm_is_active(alarm):
                    logging.debug("REQUIRED ALARM is Active [{}]: {}".format(log_entry.timestamp, alarm))
                    kpi.current_iteration.required_alarms.remove(alarm)

        if kpi.current_iteration.site_reset_timestamp and kpi.hwf_detection and entry_type == 'updates':
            kpi.hwf_detection.search_hwf_entry(dist_name=dist_name, value=log_entry.updates[dist_name])

        if self._check_if_device_info_event(kpi, dist_name, log_entry, entry_type):
            kpi.add_device_info(dist_name=dist_name, value=values)

        if kpi.start_point and self._check_if_start_point_event(kpi, dist_name, log_entry, entry_type):
            if not kpi.start_search_after and kpi.current_iteration.end_point_entries:
                logging.debug("Ending previous iteration - new start point detected")
                self._end_iteration(kpi)

            self._log_debug_for_detected_point('START', frame_index, dist_name, log_entry, kpi, entry_type)
            technology = self._get_used_technology(dist_name, values, kpi.technologies)

            kpi.add_start_entry(technology, dist_name=dist_name, timestamp=log_entry.timestamp,
                                value=values, mrbts_id=self._mrbts_id, mrbts_ids=self._mrbts_ids)
            if not kpi.current_iteration.first_start_point_entry_timestamp:
                kpi.current_iteration.first_start_point_entry_timestamp = log_entry.timestamp

        elif self._check_if_end_point_event(kpi, dist_name, log_entry, entry_type):
            if kpi.should_contain_rst_event and not kpi.current_iteration.site_reset_timestamp:
                if not isinstance(kpi.end_point, AnyStatus):
                    self._log_debug_for_ignored_entry(
                        reason="RST event has not been detected yet",
                        entry_type='END', dist_name=dist_name,
                        frame_index=frame_index, log_entry=log_entry, kpi=kpi)
                return
            if kpi.current_iteration.detected_cell_dist_names:
                # detected_cell_dist_names contains normalized names if normalize_runtime_view is enabled
                check_dist_name = kpi._normalize_dist_name(dist_name) if kpi.normalize_runtime_view else dist_name
                if check_dist_name not in kpi.current_iteration.detected_cell_dist_names:
                    self._log_debug_for_ignored_entry(
                        reason="DistName is not in 'detected_dist_names'",
                        entry_type='END', dist_name=dist_name,
                        frame_index=frame_index, log_entry=log_entry, kpi=kpi)
                    return
            if kpi.current_iteration.first_start_point_entry_timestamp and kpi.min_start_and_end_point_offset:
                if kpi.current_iteration.first_start_point_entry_timestamp + \
                        kpi.min_start_and_end_point_offset > log_entry.timestamp:
                    self._log_debug_for_ignored_entry(
                        reason="'min_start_and_end_point_offset' is set",
                        entry_type='END', dist_name=dist_name,
                        frame_index=frame_index, log_entry=log_entry, kpi=kpi)
                    return
            if kpi.current_iteration.required_alarms:
                self._log_debug_for_ignored_entry(
                    reason="still not all required alarms occurred",
                    entry_type='END', dist_name=dist_name,
                    frame_index=frame_index, log_entry=log_entry, kpi=kpi)
                return

            self._log_debug_for_detected_point('END', frame_index, dist_name, log_entry, kpi, entry_type)
            technology = self._get_used_technology(dist_name, values, kpi.technologies)
            kpi.add_end_entry(technology, dist_name=dist_name, timestamp=log_entry.timestamp, mrbts_id=self._mrbts_id,
                              mrbts_ids=self._mrbts_ids)
            if kpi.check_if_number_of_dist_names_in_start_points_and_end_points_are_the_same() or \
                    (kpi.multi_indication and kpi.check_if_number_of_indication_points_and_end_points_are_the_same()):
                if isinstance(kpi.start_point, AllEvents):
                    if not kpi.start_point.all_events_occurred():
                        return
                    kpi.start_point.reset()
                logging.debug("Ending iteration ['START POINTS == END POINTS']")
                self._end_iteration(kpi)

    def _log_debug_for_detected_point(self, point_type, frame_index, dist_name, log_entry, kpi, entry_type='updates'):
        point_type = point_type.upper()
        msg = "[{}][{} POINT DETECTED]\n".format(kpi.name, point_type.upper())
        if self.merge_ims_files:
            msg += "\tFile:\t\t{}\n".format(self._current_ims_file)
        msg += "\tFrame:\t\t{} ({})\n".format(frame_index, entry_type)
        msg += "\tTimestamp:\t{}\n".format(log_entry.timestamp)
        if dist_name is not None:
            msg += "\tDist Name:\t{}\n".format(dist_name)
            if isinstance(getattr(log_entry, entry_type), dict):
                msg += "\tValues:\t\t{}\n".format(getattr(log_entry, entry_type)[dist_name])
        logging.debug(msg)

    def _log_debug_for_ignored_entry(self, reason, entry_type, frame_index, dist_name, log_entry, kpi):
        entry_type = entry_type.upper()
        msg = "[{}] Ignoring {} point entry - {}\n".format(kpi.name, entry_type.lower(), reason)
        if self.merge_ims_files:
            msg += "\tFile:\t\t{}\n".format(self._current_ims_file)
        msg += "\tDIST_NAME: {}, FRAME: {}, TIMESTAMP: {}\n".format(frame_index, dist_name, log_entry.timestamp)
        logging.debug(msg)

    def _check_if_indication_event(self, kpi, dist_name, log_entry, entry_type):  # noqa: C901
        if kpi.start_search_after:
            event = self._get_proper_event(kpi, 'start_search_after', dist_name, entry_type)
            if event:
                if isinstance(event, datetime.datetime):
                    if log_entry.timestamp >= kpi.start_search_after and not kpi.current_iteration.indication_point:
                        return True
                elif event.compiled_pattern.search(dist_name) and (
                    isinstance(event, AnyStatus)
                    or self._check_if_any_status_matched(
                        event.status, getattr(log_entry, entry_type)[dist_name])):
                    return True
        return False

    @staticmethod
    def _get_proper_event(kpi, attribute_name, dist_name, entry_type):
        base_event = getattr(kpi, attribute_name)
        if isinstance(base_event, SequenceOfEvents):
            event = base_event.current_event_record['event']
            return event
        elif isinstance(base_event, (OneOfEvents, AllEvents)):
            for event in base_event.events:
                if event.compiled_pattern.search(dist_name) and event.entry_type == entry_type:
                    return event
        else:
            return base_event

    def _check_if_device_info_event(self, kpi, dist_name, log_entry, entry_type):
        device_info_event = kpi.device_info_event if kpi.device_info_event else kpi.current_iteration.device_info_event
        if device_info_event:
            if device_info_event.entry_type != entry_type:
                return False
            if device_info_event.compiled_pattern.search(dist_name):
                if device_info_event.status:
                    if self._check_if_any_status_matched(device_info_event.status,
                                                         getattr(log_entry, entry_type)[dist_name]):
                        return True
                else:
                    return True
        return False

    def _check_if_start_point_event(self, kpi, dist_name, log_entry, entry_type):
        if isinstance(kpi.start_point, (SiteResetRequest, datetime.datetime)):
            return False
        else:
            event = self._get_proper_event(kpi, 'start_point', dist_name, entry_type)
            if event:
                if event.compiled_pattern.search(dist_name) and (
                    isinstance(event, AnyStatus)
                    or self._check_if_any_status_matched(
                        event.status, getattr(log_entry, entry_type)[dist_name])):
                    if isinstance(kpi.start_point, AllEvents):
                        kpi.start_point.add_event_to_occurred(event)
                    return True
        return False

    def _check_if_end_point_event(self, kpi, dist_name, log_entry, entry_type):
        if kpi.current_iteration.start_point_entries or kpi.current_iteration.start_point_timestamp:
            event = self._get_proper_event(kpi, 'end_point', dist_name, entry_type)
            if event:
                if event.compiled_pattern.search(dist_name) and (
                    isinstance(event, AnyStatus)
                    or self._check_if_any_status_matched(
                        event.status, getattr(log_entry, entry_type)[dist_name])):
                    return True
        return False

    @staticmethod
    def _get_current_indication_dist_name(kpi):
        indication_point = kpi.current_iteration.indication_point
        if indication_point:
            return indication_point[0]['dist_name']

    def _end_iteration(self, kpi):
        try:
            kpi.calculate_delta()
            kpi.check_interval()
        except DataNotAvailable as e:
            msg = r"Cannot calculate {} due to: {}".format(kpi.name, repr(e))
            if self.log_warning:
                logging.warning(msg)
            kpi.exception_msg.append(msg)
        kpi.add_alarms_after_iteration(self.alarm.active_alarms)
        start = kpi.current_iteration.indication_point[0]['timestamp'] if kpi.current_iteration.indication_point else \
            kpi.current_iteration.start_point_timestamp
        kpi.add_additional_alarms_during_iteration(
            self.alarm.get_active_alarms_from_time_range(start=start,
                                                         end=kpi.current_iteration.end_point_timestamp))
        kpi.save_current_iteration()
        kpi.current_iteration.clear_current_iteration_results()
        if kpi.hwf_detection:
            kpi.hwf_detection.clear_results()
        if kpi.start_search_after and isinstance(kpi.start_search_after, SequenceOfEvents):
            kpi.start_search_after.reset()

    def _check_if_any_status_matched(self, kpi_status, entry_status):
        statuses = []
        for single_kpi_status in kpi_status:
            status = self._check_statuses_are_the_same(kpi_status=single_kpi_status, entry_status=entry_status)
            statuses.append(status)

        return any(statuses)

    @staticmethod
    def _check_statuses_are_the_same(kpi_status, entry_status, status_diff=None):
        """
        Check if defined kpi_status fall in entry_status from IMS
        :param kpi_status: defined kpi status
        :param entry_status: IMS log entry status
        :param status_diff:
        :return:
        """
        status_diff = status_diff if status_diff is not None else []

        for kpi_key in kpi_status:
            if 'stateInfo' in entry_status and 'stateInfo' not in kpi_status \
                    and any(True for key in kpi_status if 'state' in key.lower() or 'status' in key.lower()):
                entry_status = entry_status['stateInfo']
            if kpi_key in entry_status:
                if isinstance(kpi_status[kpi_key], dict):
                    Calculator._check_statuses_are_the_same(kpi_status[kpi_key],
                                                            entry_status[kpi_key],
                                                            status_diff)
                else:
                    status = Calculator._compare_single_values(kpi_status[kpi_key], entry_status[kpi_key])
                    status_diff.append(status)
            elif kpi_key == 'availabilityStatus':
                entry_status[kpi_key] = 'Online'
                status = Calculator._compare_single_values(kpi_status[kpi_key], entry_status[kpi_key])
                status_diff.append(status)
            else:
                status_diff.append(False)

        return all(status_diff)

    @staticmethod  # noqa: C901
    def _compare_single_values(kpi_value, entry_value):  # noqa: C901
        """
        Compare single value.
        :param kpi_value: object of string or ValueProperty
        :param str entry_value: IMS log entry value
        :return:
        """
        if isinstance(kpi_value, ValueProperty):
            if kpi_value.regex is False and Calculator.OPERATORS[kpi_value.operator](entry_value, kpi_value.value):
                return True
            if kpi_value.regex:
                _re = re.compile(kpi_value.value, re.IGNORECASE)
                match = _re.search(str(entry_value))
                if Calculator.OPERATORS[kpi_value.operator](match):
                    return True
        elif isinstance(kpi_value, bool):
            if kpi_value is entry_value:
                return True
        else:
            if kpi_value.lower() == str(entry_value).lower():
                return True
        return False

    @staticmethod
    def _get_used_technology(dist_name, values, technologies):
        """
        Get technology from passed dist_name
        :param str dist_name: dist_name
        :param values: values
        :param technologies: defined technologies
        :return: technology name
        """
        if values is None and 'UNBLOCK_IND' in dist_name:
            return 'COMMON'
        for technology in technologies:
            if technology.BTS_NAME in dist_name or technology.CELL_NAME in dist_name:
                return technology.__name__
            if 'targetDN' in values and technology.BTS_NAME in values['targetDN']:
                return technology.__name__
            if 'SW_UPDATE_IND' in dist_name or 'RESET_IND' in dist_name or 'RESET_PROCEDURE' in dist_name \
                    or 'PLAN_ACTIVATE_IND' in dist_name or 'SW_DOWNLOAD_REQ' in dist_name \
                    or 'SW_ROLLBACK_IND' in dist_name or re.search(DistNamePatterns.MRBTS, dist_name):
                return 'COMMON'
        return 'OTHER'

    @staticmethod
    def _get_used_technology_from_indication_point(kpi):
        ind_point = kpi.current_iteration.indication_point
        return Calculator._get_used_technology(dist_name=ind_point['dist_name'],
                                               values=ind_point['value'], technologies=kpi.technologies)

    @staticmethod
    def _get_kpi_names(kpi_names):
        """
        Get KPI names
        :param str, list kpi_names: KPI names
        :return: list of KPI names
        """
        if not isinstance(kpi_names, (list, tuple)):
            kpi_names = re.split(r'\s+', kpi_names)
        kpi_names = [kpi_name.lower() for kpi_name in kpi_names]
        return kpi_names

    def _get_kpi_instances(self, kpi_params, serial_console_connected=False):
        """
        Get instance of KPI class.
        :param dict kpi_params: Additional kpi params.
        :return: list of KPI instances
        """
        params = kpi_params if kpi_params else {}
        kpi_instances = []
        for kpi_name in self.kpi_names:
            kwargs = params.get(kpi_name, {})
            klass = Provider.provide(kpi_name=kpi_name)
            if self._accepts_kwargs(klass.__init__):
                kwargs['serial_console_connected'] = serial_console_connected
            kpi_instances.append(Provider.provide(kpi_name=kpi_name)(**kwargs))
        return kpi_instances

    @staticmethod
    def _accepts_kwargs(method):
        sig = inspect.signature(method)
        params = list(sig.parameters.values())
        return any(p.kind == inspect.Parameter.VAR_KEYWORD for p in params)
